/* ===== NI FITNESS · VISUAL EXERCISE BUILDER V2 ===== */
function escNI(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function niGroups(){return [...new Set((window.NI_ADMIN_EXERCISES||[]).map(x=>x.group))]}
function niExerciseOptions(group,selectedId){
 return (window.NI_ADMIN_EXERCISES||[]).filter(x=>!group||x.group===group).map(x=>`<option value="${x.id}" ${String(x.id)===String(selectedId)?'selected':''}>${escNI(x.name)}</option>`).join('');
}
function niExerciseRow(x={}){
 const found=(window.NI_ADMIN_EXERCISES||[]).find(e=>String(e.id)===String(x.exercise_id||x.id))||
             (window.NI_ADMIN_EXERCISES||[]).find(e=>e.name===x.name);
 const group=found?.group||x.group||niGroups()[0]||'';
 const id=found?.id||'';
 return `<div class="ni-ex-row" style="padding:12px;margin:8px 0;border:1px solid #303036;border-radius:14px">
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
   <label>Группа<select class="ni-ex-group">${niGroups().map(g=>`<option ${g===group?'selected':''}>${escNI(g)}</option>`).join('')}</select></label>
   <label>Упражнение<select class="ni-ex-select"><option value="">Выбрать…</option>${niExerciseOptions(group,id)}</select></label>
  </div>
  <div class="ni-ex-preview" style="font-size:11px;color:#999;margin:8px 0"></div>
  <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:7px">
   <label>Подходы<input class="ni-sets" inputmode="numeric" value="${escNI(x.sets||3)}"></label>
   <label>Повторы<input class="ni-reps" value="${escNI(x.reps||'8-12')}"></label>
   <label>Отдых<input class="ni-rest" value="${escNI(x.rest||'90 сек')}"></label>
  </div>
  <label>Комментарий к упражнению<input class="ni-note" value="${escNI(x.note||'')}" placeholder="Темп, RIR, техника..."></label>
  <div style="display:flex;gap:7px"><button type="button" class="ni-up">↑</button><button type="button" class="ni-down">↓</button><button type="button" class="ni-remove">Удалить</button></div>
 </div>`;
}
function niPreview(row){
 const id=row.querySelector('.ni-ex-select')?.value;
 const e=(window.NI_ADMIN_EXERCISES||[]).find(x=>String(x.id)===String(id));
 const p=row.querySelector('.ni-ex-preview'); if(!p)return;
 p.innerHTML=e?`<b>${escNI(e.muscles||'')}</b><br>${escNI(e.equipment||'')} · ${escNI(e.technique||'')}`:'';
}
function bindNIExerciseRows(root=document){
 root.querySelectorAll('.ni-ex-row').forEach(row=>{
  const g=row.querySelector('.ni-ex-group'),sel=row.querySelector('.ni-ex-select');
  g.onchange=()=>{sel.innerHTML='<option value="">Выбрать…</option>'+niExerciseOptions(g.value,'');niPreview(row)};
  sel.onchange=()=>niPreview(row);
  row.querySelector('.ni-remove').onclick=()=>row.remove();
  row.querySelector('.ni-up').onclick=()=>{const p=row.previousElementSibling;if(p&&p.classList.contains('ni-ex-row'))row.parentNode.insertBefore(row,p)};
  row.querySelector('.ni-down').onclick=()=>{const n=row.nextElementSibling;if(n&&n.classList.contains('ni-ex-row'))row.parentNode.insertBefore(n,row)};
  niPreview(row);
 });
}
trainingDayBlock=function(day={title:'',exercises:[]}){
 return `<div class="card training-day-edit" style="margin:10px 0">
  <label>День / название<input class="td-title" value="${escNI(day.title||'')}" placeholder="Например: День 1 · Ноги"></label>
  <div class="ni-exercises">${(day.exercises||[]).map(niExerciseRow).join('')}</div>
  <button type="button" class="ni-add-ex wide">+ Добавить упражнение из базы</button>
  <details style="margin-top:9px"><summary class="muted">Добавить упражнение вручную</summary>
   <textarea class="td-manual" rows="3" placeholder="Название | 3 | 10-12 | 90 сек"></textarea>
  </details>
  <button type="button" class="remove-training-day">Удалить день</button>
 </div>`;
};
bindTrainingDayRemove=function(){
 $$('.remove-training-day').forEach(b=>b.onclick=()=>b.closest('.training-day-edit').remove());
 $$('.ni-add-ex').forEach(b=>b.onclick=()=>{const box=b.closest('.training-day-edit').querySelector('.ni-exercises');box.insertAdjacentHTML('beforeend',niExerciseRow({}));bindNIExerciseRows(box)});
 bindNIExerciseRows();
};
readTrainingDays=function(){
 return $$('.training-day-edit').map((el,i)=>{
  const title=el.querySelector('.td-title').value.trim()||`День ${i+1}`;
  const visual=[...el.querySelectorAll('.ni-ex-row')].map(row=>{
   const id=row.querySelector('.ni-ex-select').value;
   const e=(window.NI_ADMIN_EXERCISES||[]).find(x=>String(x.id)===String(id));
   if(!e)return null;
   return {exercise_id:e.id,name:e.name,group:e.group,image:e.image,technique:e.technique,muscles:e.muscles,equipment:e.equipment,
    joints:e.joints,assist:e.assist,breath:e.breath,mistake:e.mistake,sets:Number(row.querySelector('.ni-sets').value)||3,
    reps:row.querySelector('.ni-reps').value||'8-12',rest:row.querySelector('.ni-rest').value||'90 сек',note:row.querySelector('.ni-note').value.trim()};
  }).filter(Boolean);
  const manual=(el.querySelector('.td-manual')?.value||'').split('\n').map(s=>s.trim()).filter(Boolean).map(line=>{
   const p=line.split('|').map(x=>x.trim());return {name:p[0],sets:Number(p[1])||3,reps:p[2]||'8-12',rest:p[3]||'90 сек',manual:true};
  });
  return {title,exercises:[...visual,...manual]};
 });
};